  function 成长技能模板项_七怪(写入类型, 写入路径, 触发事件标识, 触发关键词, 需求魂环数, 效果键, 额外 = {}) {
    const 效果 = 效果补录[效果键];
    const 技能数据 = Object.freeze({
      魂技名: 效果.魂技名,
      画面描述: 效果.画面描述,
      效果描述: 效果.效果描述,
      承载方式: 效果.承载方式,
      消耗: 效果.消耗,
      前摇: 效果.前摇,
      附带属性: 效果.附带属性,
      _效果数组: 效果._效果数组,
      副作用列表: 效果.副作用列表,
    });
    return Object.freeze({ 魂技名: 效果.魂技名, 写入类型, 写入路径, 触发事件标识, 触发关键词: Object.freeze(触发关键词), 需求魂环数, ...额外, 技能数据 });
  }

